import{_ as e,o,c as t,a5 as r}from"./chunks/framework.CXvGqWf0.js";const p=JSON.parse('{"title":"漫画 · 第 54 话 性能审计与监控","description":"","frontmatter":{},"headers":[],"relativePath":"comics/perf/EP.54-audit-monitoring.md","filePath":"comics/perf/EP.54-audit-monitoring.md","lastUpdated":1793421609000}'),i={name:"comics/perf/EP.54-audit-monitoring.md"};function n(l,a,h,s,d,u){return o(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="漫画-·-第-54-话-性能审计与监控" tabindex="-1">漫画 · 第 54 话 性能审计与监控 <a class="header-anchor" href="#漫画-·-第-54-话-性能审计与监控" aria-label="Permalink to &quot;漫画 · 第 54 话 性能审计与监控&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/perf/06-performance-audit-monitoring">docs/perf/06-performance-audit-monitoring.md</a> ｜ 原画：<a href="./EP.54-audit-monitoring.svg">EP.54-audit-monitoring.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，本话主角。上线一个月后回头看监控，发现性能大屏挂了三个月没人看，指标全是问号。</li><li><strong>标签君</strong>：结构师，把 Lighthouse、火焰图、RUM 三只眼排成一条流水线，最后落到一道 CI 门禁。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>项目上线第 30 天，老板问&quot;我们性能怎么样&quot;，没人答得上来：没有基线、没有门禁、没有告警，大屏只是装饰。像素酱这才明白，性能优化不是上线前突击一次，而是要变成每次提交都会跑的机制。标签君给出方案：三只眼负责看，一道门负责拦。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>三个缺口依次咬人：没有基线，就不知道 2.3s 算好还是坏；没有门禁，性能回退照样合并；没有告警，线上 p75 越线也没人知道。结果就是监控大屏挂了三个月，指标全是问号。性能问题不是&quot;没人会优化&quot;，而是&quot;没人负责度量&quot;。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>三只眼各有分工：Lighthouse（Lab）在固定环境下跑分，可复现、可进 CI，负责发现回归；火焰图定位长任务与热点函数，负责归因；RUM（Field）采集真实用户的 p75，负责决定先修哪一屏。三者汇入同一份预算：LCP 2.5s、INP 200ms、CLS 0.1，并与基线对比。出口有两个：CI 门禁超预算阻断合并，线上告警 p75 越线通知值班。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>PR #1288 跑了性能预算：LCP 2.3s 与 INP 180ms 通过，CLS 0.12 和 Bundle +38KB 两项 FAIL，PR 不可合并。线上 p75 曲线在第 5 天越过 200ms 阈值，值班收到告警，归因是一次未分包的第三方 SDK 渲染阻塞。审计不是月底做一次报告，而是每次提交都在跑的门。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>Lab + Field 并用：Lighthouse 复现归因，RUM 决定优化优先级。</li><li>预算进 CI：阈值与基线双门禁，超了就阻断合并，别靠自觉。</li><li>先归因再优化：火焰图找热点，改一处、量一次，别凭感觉重写。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：CI 里 Lighthouse 分数一直是 98，线上 RUM 却持续报警，两边谁错了？</p><p><strong>答</strong>：都没错，它们测的不是同一件事。Lighthouse 在固定机型、固定网络、冷缓存下跑，覆盖不了真实用户的低端机、弱网、热缓存与复杂交互；RUM 采集的是分布，能暴露长尾。正确做法是让 Lab 守住&quot;不回退&quot;，让 Field 决定&quot;先修谁&quot;，并把线上 p75 的分桶（设备、地区、页面）反哺到 Lab 的场景配置里。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>Lighthouse CI 预算门禁 + RUM p75 看板模拟：<a href="./../../examples/perf/06-performance-audit-monitoring">examples/perf/06-performance-audit-monitoring</a></li><li>用 Performance 面板录制一段交互，导出火焰图，找出最长的那个任务并标注归因。</li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>性能优化篇到此完结：度量 → 首屏 → 渲染 → 主线程 → 缓存 → 审计监控，六话串成一条完整闭环。下一段旅程，我们把镜头转向工程化与部署实战。</p>',22)])])}const m=e(i,[["render",n]]);export{p as __pageData,m as default};
